307	// kustomizationRules lists every top level field of a kustomization of
308	// kustomize v5.8.3. A field that is not here is refused as unknown (kustomize
309	// rejects it too, but the gate does not rely on that).
310	var kustomizationRules = map[string]gateRule{
311		"apiVersion": dataRule, "kind": dataRule, "metadata": dataRule,
312		"namePrefix": dataRule, "nameSuffix": dataRule, "namespace": dataRule,
313		"commonLabels": dataRule, "labels": dataRule, "commonAnnotations": dataRule,
314		"images": dataRule, "imageTags": dataRule, "replicas": dataRule, "vars": dataRule,
315		"sortOptions": dataRule, "generatorOptions": dataRule, "buildMetadata": dataRule,
316	
317		"resources": listOf(baseRule), "bases": listOf(baseRule), "components": listOf(baseRule),
318		"crds": listOf(fileRule), "configurations": listOf(fileRule),
319		"openapi": pathOnly,
320	
321		"patches": listOf(pathOnly), "patchesJson6902": listOf(pathOnly),
322		"patchesStrategicMerge": listOf(patchRule),
323		"replacements":          listOf(pathOnly),
324	
325		"configMapGenerator": listOf(mapOf(kvSources)),
326		"secretGenerator":    listOf(mapOf(kvSources)),
327	
328		"helmGlobals": mapOf(map[string]gateRule{"chartHome": fileRule, "configHome": fileRule}),
329		// A chart name is a reference too: helm pulls what an oci:// name says.
330		"helmCharts": listOf(mapOf(map[string]gateRule{
331			"name": fileRule, "repo": fileRule, "valuesFile": fileRule, "additionalValuesFiles": listOf(fileRule), "chartHome": fileRule,
332		})),
333		"helmChartInflationGenerator": listOf(mapOf(map[string]gateRule{
334			"chartName": fileRule, "chartRepoUrl": fileRule, "chartHome": fileRule, "helmHome": fileRule, "values": fileRule,
335			"helmBin": neverRule, "extraArgs": neverRule,
336		})),
