341	// builtinPlugins are the kinds of apiVersion builtin that kustomize v5.8.3 loads
342	// (builtinhelpers), with the fields of their configuration that name a file. The
343	// kinds with no such field read nothing from the file system: they take names,
344	// labels, an image, a count or a policy, so they are accepted as they are.
345	var builtinPlugins = map[string]map[string]gateRule{
346		"ConfigMapGenerator": kvSources, "SecretGenerator": kvSources,
347		"PatchTransformer": {"path": fileRule}, "PatchJson6902Transformer": {"path": fileRule},
348		"PatchStrategicMergeTransformer": {"paths": listOf(patchRule)},
349		"ReplacementTransformer":         {"replacements": listOf(pathOnly)},
350		"ValueAddTransformer":            {"targetFilePath": fileRule},
351		"HelmChartInflationGenerator": {
352			"name": fileRule, "chartHome": fileRule, "configHome": fileRule, "repo": fileRule, "valuesFile": fileRule,
353			"additionalValuesFiles": listOf(fileRule),
354		},
355	
356		"AnnotationsTransformer": nil, "LabelTransformer": nil, "NamespaceTransformer": nil,
357		"PrefixTransformer": nil, "SuffixTransformer": nil, "PrefixSuffixTransformer": nil,
358		"ImageTagTransformer": nil, "ReplicaCountTransformer": nil, "HashTransformer": nil,
359		"IAMPolicyGenerator": nil,
360	}
361	
362	// functionAnnotations make kustomize run a program or a container for a plugin.
363	var functionAnnotations = []string{"config.kubernetes.io/function", "config.k8s.io/function"}
364	
365	// kustomizationNames are the file names kustomize recognizes.
366	var kustomizationNames = []string{"kustomization.yaml", "kustomization.yml", "Kustomization"}
367	
368	// ── The walk ─────────────────────────────────────────────────────────────────
369	
370	// gate is one run of vetOverlay.
371	type gate struct {
372		ctx     context.Context //nolint:containedctx // one run of the gate, never stored
373		root    string          // the limit, absolute, symbolic links resolved
374		lim     gateLimits
375		visited map[string]bool // directories entered, by real path
376		count   int             // kustomizations read
377		read    int64           // bytes read
378	}
379	
380	// gateSite is where a value was read: file is the file it is in (relative to
381	// the limit), dir the directory its references are relative to (the one of the
382	// kustomization, also for a plugin file), depth how far below the first overlay.
383	type gateSite struct {
384		file  string
385		dir   string
386		depth int
387	}
388	
389	func (s gateSite) remote(field, ref, reason string) gateVerdict {
390		return gateVerdict{Kind: gateRemote, File: s.file, Field: field, Ref: ref, Reason: reason}
391	}
392	
393	func (s gateSite) unchecked(field, ref, reason string) gateVerdict {
394		return gateVerdict{Kind: gateUnchecked, File: s.file, Field: field, Ref: ref, Reason: reason}
395	}
396	
397	// vetOverlay reads the overlay directory (absolute) and everything it pulls in,
398	// inside root (absolute; the gate resolves symbolic links itself).
399	func vetOverlay(ctx context.Context, root, overlay string, lim gateLimits) gateVerdict {
400		unchecked := func(reason string) gateVerdict { return gateVerdict{Kind: gateUnchecked, Reason: reason} }
401		root, err := filepath.Abs(root)
402		if err != nil {
403			return unchecked("the limit of the paths cannot be resolved")
404		}
405		if root, err = filepath.EvalSymlinks(root); err != nil {
406			return unchecked("the limit of the paths cannot be resolved")
407		}
408		if overlay, err = filepath.Abs(overlay); err != nil {
409			return unchecked("the overlay cannot be resolved")
410		}
411		real, err := filepath.EvalSymlinks(overlay)
412		switch {
413		case isMissing(err):
414			return gateVerdict{} // kustomize reports it, and fetches nothing
415		case err != nil:
416			return unchecked("the overlay cannot be resolved")
417		case !within(root, real):
418			return unchecked("the overlay is outside the repository")
419		}
420		g := &gate{ctx: ctx, root: root, lim: lim, visited: map[string]bool{}}
421		return g.dir(real, 0)
422	}
423	
424	// within reports whether p is root or below it, lexically.
425	func within(root, p string) bool {
426		rel, err := filepath.Rel(root, p)
427		return err == nil && rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator))
428	}
429	
430	// isMissing reports whether err says a path is not there (or has a file where a
431	// directory should be): nothing for kustomize to load, so nothing to fetch.
432	func isMissing(err error) bool {
433		return err != nil && (errors.Is(err, fs.ErrNotExist) || errors.Is(err, syscall.ENOTDIR))
434	}
435	
436	// rel is p relative to the limit, with forward slashes.
437	func (g *gate) rel(p string) string {
438		r, err := filepath.Rel(g.root, p)
439		if err != nil {
440			return filepath.ToSlash(p)
441		}
442		return filepath.ToSlash(r)
443	}
444	
445	// dir judges the kustomization of one directory (a real path inside the limit)
446	// and, through it, everything it pulls in. A directory with none holds nothing
447	// to follow.
448	func (g *gate) dir(real string, depth int) gateVerdict {
449		if g.visited[real] {
450			return gateVerdict{}
451		}
452		g.visited[real] = true
453		where := gateSite{file: g.rel(real), dir: real, depth: depth}
454		switch {
455		case g.ctx.Err() != nil:
456			return where.unchecked("", "", "the check was cancelled")
457		case depth > g.lim.Depth:
458			return where.unchecked("", "", fmt.Sprintf("overlays are nested more than %d levels deep", g.lim.Depth))
459		}
460		file, v := g.kustomizationFile(real)
461		if file == "" {
462			return v
463		}
464		if g.count++; g.count > g.lim.Visited {
465			return where.unchecked("", "", fmt.Sprintf("more than %d kustomizations are pulled in", g.lim.Visited))
466		}
467		site := gateSite{file: g.rel(file), dir: real, depth: depth}
468		// The kustomization file may itself be a link: what is read is what it names.
469		if target, err := filepath.EvalSymlinks(file); err != nil || !within(g.root, target) {
470			return site.unchecked("", "", "the kustomization file leaves the repository through a symbolic link")
471		}
472		node, reason := g.readYAML(file)
473		if reason != "" {
474			return site.unchecked("", "", reason)
475		}
476		return g.applyMap(mapOf(kustomizationRules), node, "", site, true)
477	}
478	
479	// kustomizationFile is the kustomization file of dir, "" when there is none, or a
480	// verdict when there are several.
481	func (g *gate) kustomizationFile(dir string) (string, gateVerdict) {
482		var found []string
483		for _, name := range kustomizationNames {
484			p := filepath.Join(dir, name)
485			if _, err := os.Lstat(p); err == nil {
486				found = append(found, p)
487			} else if !isMissing(err) {
488				return "", gateSite{file: g.rel(p)}.unchecked("", "", "it cannot be read ("+errReason(err)+")")
489			}
490		}
491		switch len(found) {
492		case 0:
493			return "", gateVerdict{}
494		case 1:
495			return found[0], gateVerdict{}
496		}
497		return "", gateSite{file: g.rel(found[0])}.unchecked("", "", "the directory holds more than one kustomization file")
498	}
499	
500	// readYAML reads a file of the overlay, within what is left of the ceilings.
501	func (g *gate) readYAML(file string) (*yaml.Node, string) {
502		data, reason := readGateFile(file, min(g.lim.FileBytes, g.lim.TotalBytes-g.read))
503		if reason != "" {
504			return nil, reason
505		}
506		g.read += int64(len(data))
507		return parseGateYAML(data)
508	}
509	
510	func join(prefix, name string) string {
511		if prefix == "" {
512			return name
513		}
514		return prefix + "." + name
515	}
516	
517	func isNull(n *yaml.Node) bool { return n.Kind == yaml.ScalarNode && n.Tag == "!!null" }
518	
519	// apply judges the value n of field by r.
520	func (g *gate) apply(r gateRule, n *yaml.Node, field string, s gateSite) gateVerdict {
521		if isNull(n) || r.kind == gateData {
522			return gateVerdict{}
523		}
524		switch r.kind {
525		case gateList:
526			return g.applyList(r, n, field, s)
527		case gateMap:
528			return g.applyMap(r, n, field, s, false)
529		case gateNever:
530			return g.applyNever(n, field, s)
531		case gatePatch:
532			if n.Kind == yaml.MappingNode { // inline, as data; kustomize rejects it
533				return gateVerdict{}
534			}
535		}
536		if n.Kind != yaml.ScalarNode || n.Tag != "!!str" {
537			return s.unchecked(field, "", "a reference that is not a string")
538		}
539		return g.applyString(r.kind, n.Value, field, s)
540	}
541	
542	func (g *gate) applyList(r gateRule, n *yaml.Node, field string, s gateSite) gateVerdict {
543		if n.Kind != yaml.SequenceNode {
544			return s.unchecked(field, "", "a value that is not a list")
545		}
546		for i, e := range n.Content {
547			if v := g.apply(*r.elem, e, fmt.Sprintf("%s[%d]", field, i), s); v.Kind != gateOK {
548				return v
549			}
550		}
551		return gateVerdict{}
552	}
553	
554	// applyMap judges the entries of a mapping. closed is the kustomization itself,
555	// where a field that kustomizationRules does not list is refused; elsewhere an
556	// entry no rule lists holds no reference.
557	func (g *gate) applyMap(r gateRule, n *yaml.Node, field string, s gateSite, closed bool) gateVerdict {
558		if n.Kind != yaml.MappingNode {
559			return s.unchecked(field, "", "a value that is not a mapping")
560		}
561		for i := 0; i+1 < len(n.Content); i += 2 {
562			key := n.Content[i].Value
563			sub, known := lookupRule(r.fields, key)
564			if !known && closed {
565				return s.unchecked(join(field, key), "", "a field that kustomize v5.8.3 does not have")
566			}
567			if !known {
568				continue
569			}
570			if v := g.apply(sub, n.Content[i+1], join(field, key), s); v.Kind != gateOK {
571				return v
572			}
573		}
574		return gateVerdict{}
575	}
576	
577	// applyNever refuses any value of a field that names a program to run or its
578	// arguments.
579	func (g *gate) applyNever(n *yaml.Node, field string, s gateSite) gateVerdict {
580		var parts []string
581		if n.Kind == yaml.ScalarNode {
582			parts = append(parts, n.Value)
583		}
584		for _, c := range n.Content {
585			parts = append(parts, c.Value)
586		}
587		ref := strings.Join(parts, " ")
588		if ref == "" {
589			return gateVerdict{}
590		}
591		return s.remote(field, ref, "it names a program to run or arguments for it")
592	}
593	
594	func (g *gate) applyString(kind gateRuleKind, value, field string, s gateSite) gateVerdict {
595		switch kind {
596		case gateFileSource:
597			parts := strings.Split(value, "=")
598			if len(parts) > 2 {
599				return s.unchecked(field, value, "a files entry with more than one equal sign")
600			}
601			return g.reference(parts[len(parts)-1], false, field, s)
602		case gatePlugin:
603			if strings.Contains(value, "\n") {
604				return g.inlinePlugin(value, field, s)
605			}
606			return g.pluginPath(value, field, s)
607		case gatePatch:
608			if strings.Contains(value, "\n") {
609				if inlineResources(value) {
610					return gateVerdict{}
611				}
612				return s.unchecked(field, "", "text that is neither a path nor a patch")
613			}
614			return g.reference(value, false, field, s)
615		}
616		return g.reference(value, kind == gateBase, field, s)
617	}
618	
619	// inlineResources reports whether text is what kustomize reads as an inline
620	// patch: documents that are Kubernetes objects.
621	func inlineResources(text string) bool {
622		dec := yaml.NewDecoder(strings.NewReader(text))
623		found := false
624		for {
625			var doc yaml.Node
626			err := dec.Decode(&doc)
627			if errors.Is(err, io.EOF) {
628				return found
629			}
630			if err != nil || doc.Kind != yaml.DocumentNode || len(doc.Content) != 1 || !hasKey(doc.Content[0], "kind") {
631				return false
632			}
633			found = true
634		}
635	}
636	
637	// hasKey reports whether n is a mapping with a key of exactly this name.
638	func hasKey(n *yaml.Node, name string) bool {
639		return mapGet(n, name) != nil
640	}
641	
642	// mapGet is the value of the key spelled exactly name in the mapping n.
643	func mapGet(n *yaml.Node, name string) *yaml.Node {
644		if n == nil || n.Kind != yaml.MappingNode {
645			return nil
646		}
647		for i := 0; i+1 < len(n.Content); i += 2 {
648			if n.Content[i].Value == name {
649				return n.Content[i+1]
650			}
651		}
652		return nil
653	}
654	
655	// reference judges one reference: it must be local, and below the limit once
656	// symbolic links are resolved. A directory is read in turn when follow says so.
657	func (g *gate) reference(ref string, follow bool, field string, s gateSite) gateVerdict {
658		real, found, v := g.resolve(ref, field, s)
659		if v.Kind != gateOK || !found || !follow {
660			return v
661		}
662		info, err := os.Stat(real)
663		switch {
664		case err != nil:
665			return s.unchecked(field, ref, "it cannot be read ("+errReason(err)+")")
666		case info.IsDir():
667			return g.dir(real, s.depth+1)
668		}
669		return gateVerdict{}
670	}
671	
672	// resolve turns a reference of the kustomization at s.dir into a real path. found
673	// is false for a path that is not there: kustomize reports it and fetches nothing.
674	func (g *gate) resolve(ref, field string, s gateSite) (real string, found bool, v gateVerdict) {
675		if ref == "" {
676			return "", false, gateVerdict{} // the directory of the kustomization itself
677		}
678		if ok, reason := localRef(ref); !ok {
679			return "", false, s.remote(field, ref, reason)
680		}
681		cand := filepath.Join(s.dir, filepath.FromSlash(ref))
682		if !within(g.root, cand) {
683			return "", false, s.unchecked(field, ref, "it leaves the repository")
684		}
685		real, err := filepath.EvalSymlinks(cand)
686		switch {
687		case isMissing(err):
688			return "", false, gateVerdict{}
689		case err != nil:
690			return "", false, s.unchecked(field, ref, "it cannot be resolved ("+errReason(err)+")")
691		case !within(g.root, real):
692			return "", false, s.unchecked(field, ref, "it leaves the repository through a symbolic link")
693		}
694		return real, true, gateVerdict{}
695	}
696	
697	// pluginPath judges an entry of generators, transformers or validators that is
698	// not inline: a plugin configuration file, or a directory with a kustomization.
699	func (g *gate) pluginPath(ref, field string, s gateSite) gateVerdict {
700		real, found, v := g.resolve(ref, field, s)
701		if v.Kind != gateOK || !found {
702			return v
703		}
704		info, err := os.Stat(real)
705		switch {
706		case err != nil:
707			return s.unchecked(field, ref, "it cannot be read ("+errReason(err)+")")
708		case info.IsDir():
709			return g.dir(real, s.depth+1)
710		}
711		file := gateSite{file: g.rel(real), dir: s.dir, depth: s.depth}
712		node, reason := g.readYAML(real)
713		if reason != "" {
714			return file.unchecked("", "", reason)
715		}
716		return g.pluginConfig(node, "", file)
717	}
718	
719	// inlinePlugin judges a plugin configuration written in the kustomization.
720	func (g *gate) inlinePlugin(text, field string, s gateSite) gateVerdict {
721		node, reason := parseGateYAML([]byte(text))
722		if reason != "" {
723			return s.unchecked(field, "", "an inline plugin configuration: "+reason)
724		}
725		return g.pluginConfig(node, field, s)
726	}
727	
728	// pluginConfig judges the configuration of a plugin: a builtin one of a known
729	// kind, that runs no function, whose fields that name a file are local.
730	func (g *gate) pluginConfig(node *yaml.Node, prefix string, s gateSite) gateVerdict {
731		scalar := func(name string) string {
732			if n := mapGet(node, name); n != nil && n.Kind == yaml.ScalarNode && n.Tag == "!!str" {
733				return n.Value
734			}
735			return ""
736		}
737		if version := scalar("apiVersion"); version != "builtin" {
738			return s.unchecked(join(prefix, "apiVersion"), "", fmt.Sprintf("a plugin of apiVersion %q: only builtin plugins are read", version))
739		}
740		kind := scalar("kind")
741		fields, known := builtinPlugins[kind]
742		if !known {
743			return s.unchecked(join(prefix, "kind"), "", fmt.Sprintf("a builtin plugin of kind %q, which the gate does not know", kind))
744		}
745		if annotations := mapGet(mapGet(node, "metadata"), "annotations"); annotations != nil && annotations.Kind == yaml.MappingNode {
746			for i := 0; i+1 < len(annotations.Content); i += 2 {
747				for _, name := range functionAnnotations {
748					if strings.EqualFold(annotations.Content[i].Value, name) {
749						return s.unchecked(join(prefix, "metadata.annotations"), "", "a function annotation, which makes kustomize run a program")
750					}
751				}
752			}
753		}
754		return g.apply(mapOf(fields), node, prefix, s)
755	}
